/**
 * Airport lookup for the setup flow.
 *
 * Backed by data/airports.json, generated by scripts/build-airports.mjs from
 * the aviationweather.gov station cache (every METAR-reporting station with a
 * 4-letter ICAO code) enriched with OurAirports names and cities.
 */

import { readFileSync } from 'fs';
import { dirname, join } from 'path';
import { fileURLToPath } from 'url';

const __dirname = dirname(fileURLToPath(import.meta.url));
// Same depth from src/services and dist/services.
const DATA_FILE = join(__dirname, '..', '..', 'data', 'airports.json');

/** One row of data/airports.json. */
export interface AirportRecord {
  icao: string;
  name: string;
  city: string;
  lat: number;
  lon: number;
  taf: 0 | 1;
  /** AWC station priority; lower is more significant. */
  p: number;
  iata?: string;
  /** Alternate names / former codes, from OurAirports. */
  kw?: string;
}

/** Shape returned by GET /api/setup/airports. */
export interface AirportSearchResult {
  icao: string;
  name: string;
  city: string;
  lat: number;
  lon: number;
  taf: boolean;
  iata?: string;
  /** Great-circle distance from the query point, nearby search only. */
  distanceNm?: number;
}

let airports: AirportRecord[] | null = null;

export function loadAirports(): AirportRecord[] {
  if (!airports) {
    airports = JSON.parse(readFileSync(DATA_FILE, 'utf-8')) as AirportRecord[];
  }
  return airports;
}

function toResult(a: AirportRecord): AirportSearchResult {
  const result: AirportSearchResult = {
    icao: a.icao,
    name: a.name,
    city: a.city,
    lat: a.lat,
    lon: a.lon,
    taf: a.taf === 1,
  };
  if (a.iata) result.iata = a.iata;
  return result;
}

export function getAirport(icao: string): AirportSearchResult | null {
  const code = icao.trim().toUpperCase();
  const found = loadAirports().find((a) => a.icao === code);
  return found ? toResult(found) : null;
}

function escapeRegExp(s: string): string {
  return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

/**
 * Rank an airport against a query. Lower is better; null means no match.
 *   0 exact ICAO, 1 exact IATA, 2 ICAO prefix,
 *   3 a word in name/city/keywords starts with the query, 4 substring match.
 */
function rank(a: AirportRecord, q: string, wordStart: RegExp): number | null {
  if (a.icao === q) return 0;
  if (a.iata === q) return 1;
  if (a.icao.startsWith(q)) return 2;
  const text = `${a.name} ${a.city} ${a.kw || ''}`.toUpperCase();
  if (wordStart.test(text)) return 3;
  if (text.includes(q)) return 4;
  return null;
}

const EARTH_RADIUS_NM = 3440.065;

/** Great-circle distance in nautical miles. */
export function distanceNm(lat1: number, lon1: number, lat2: number, lon2: number): number {
  const toRad = (d: number) => (d * Math.PI) / 180;
  const dLat = toRad(lat2 - lat1);
  const dLon = toRad(lon2 - lon1);
  const a =
    Math.sin(dLat / 2) ** 2 +
    Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) * Math.sin(dLon / 2) ** 2;
  return 2 * EARTH_RADIUS_NM * Math.asin(Math.sqrt(a));
}

/**
 * Airports closest to a point, nearest first. Used to suggest a home airport
 * once the setup flow knows where the mirror is.
 */
export function nearbyAirports(lat: number, lon: number, limit = 8): AirportSearchResult[] {
  if (!Number.isFinite(lat) || !Number.isFinite(lon) || Math.abs(lat) > 90 || Math.abs(lon) > 180) {
    return [];
  }
  const scored = loadAirports().map((a) => ({ a, d: distanceNm(lat, lon, a.lat, a.lon) }));
  scored.sort((x, y) => x.d - y.d || x.a.p - y.a.p);
  return scored
    .slice(0, limit)
    .map(({ a, d }) => ({ ...toResult(a), distanceNm: Math.round(d * 10) / 10 }));
}

/**
 * Search airports by ICAO, IATA, name, city or keyword.
 * Results are ordered by match quality, then station significance.
 */
export function searchAirports(query: string, limit = 10): AirportSearchResult[] {
  const q = query.trim().toUpperCase().replace(/\s+/g, ' ');
  if (q.length < 2) return [];

  const wordStart = new RegExp(`(^|[^A-Z0-9])${escapeRegExp(q)}`);
  const scored: Array<{ a: AirportRecord; score: number }> = [];

  for (const a of loadAirports()) {
    const score = rank(a, q, wordStart);
    if (score !== null) scored.push({ a, score });
  }

  scored.sort((x, y) => x.score - y.score || x.a.p - y.a.p || x.a.icao.localeCompare(y.a.icao));

  return scored.slice(0, limit).map(({ a }) => toResult(a));
}
